<script setup lang="ts">
import { ref, watch } from 'vue'
import AppIcon from '../../../../../shared/components/layout/AppIcon.vue'
import FormTextarea from '../../../../../shared/components/form/FormTextarea.vue'
import type { ProjectExpense } from '../../types/expense'
const props = defineProps<{ expense: ProjectExpense | null; submitting: boolean; error: string }>()
const emit = defineEmits<{ close: []; confirm: [reason: string] }>()
const reason = ref(''); const validation = ref('')
watch(() => props.expense?.id, () => { reason.value = ''; validation.value = '' })
function confirm() { if (reason.value.trim().length < 5) { validation.value = 'Alasan koreksi wajib diisi minimal 5 karakter.'; return } emit('confirm', reason.value.trim()) }
</script>
<template><Teleport to="body"><div v-if="props.expense" class="backdrop" @click.self="!props.submitting && emit('close')"><section class="card" role="dialog" aria-modal="true" aria-labelledby="void-title"><header><span class="icon"><AppIcon name="rotate-ccw" :size="19" /></span><button type="button" aria-label="Tutup" @click="emit('close')"><AppIcon name="x" :size="18" /></button></header><h2 id="void-title">Koreksi pengeluaran?</h2><p>{{ props.expense.code }} akan ditandai dikoreksi, bukan dihapus. Riwayat transaksi tetap tersimpan.</p><label for="void-reason">Alasan koreksi <i>*</i><FormTextarea id="void-reason" v-model="reason" rows="3" maxlength="1000" minlength="5" required placeholder="Jelaskan alasan koreksi" /></label><div v-if="validation || props.error" class="error" role="alert">{{ validation || props.error }}</div><footer><button type="button" class="secondary" :disabled="props.submitting" @click="emit('close')">Kembali</button><button type="button" class="primary" :disabled="props.submitting" @click="confirm">{{ props.submitting ? 'Memproses...' : 'Koreksi pengeluaran' }}</button></footer></section></div></Teleport></template>
<style scoped>
